'use strict';
(()=>{
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function get(key){try{const value=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(value)?value.filter(x=>x&&typeof x==='object'):[]}catch{return []}}
function put(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{message('Your browser cannot save locally. You can still copy this page’s link.');return false}}
function message(s){document.querySelector('#atlas-message').textContent=s}
function relative(){return location.pathname.split('/').pop()+location.search+location.hash}
function safe(url){try{const u=new URL(url,location.href);return u.origin===location.origin&&u.pathname.startsWith(location.pathname.slice(0,location.pathname.lastIndexOf('/')+1))}catch{return false}}
function count(){document.querySelector('#atlas-saved').textContent='Saved ('+get('atlas-favorites').length+')';document.querySelector('#atlas-compare').textContent='Compare ('+get('atlas-compare').length+')'}
window.Atlas={esc,get,message,save(title,url=relative()){if(!safe(url))return;const items=get('atlas-favorites');if(!items.some(x=>x.url===url))items.push({title:String(title).slice(0,180),url});if(put('atlas-favorites',items)){message('Saved on this browser.');count()}},addCompare(table,id,title){if(!['heroes','monsters','npcs','static-items'].includes(table)){message('Comparison supports heroes, monsters, NPCs and items.');return}let items=get('atlas-compare');if(items.length>=4&&!items.some(x=>x.table===table&&String(x.id)===String(id))){message('Compare up to four entries. Remove one on the comparison page first.');return}if(!items.some(x=>x.table===table&&String(x.id)===String(id)))items.push({table,id,title});if(put('atlas-compare',items)){message('Added to comparison.');count()}},setCompare(items){put('atlas-compare',items);count()}};
document.addEventListener('DOMContentLoaded',()=>{const bar=document.createElement('div');bar.className='atlas-tools';bar.innerHTML='<button id="atlas-save">☆ Save view</button><button id="atlas-share">Copy link</button><button id="atlas-saved">Saved</button><a id="atlas-compare" href="compare.html">Compare</a><span id="atlas-message" role="status"></span>';document.body.append(bar);const dialog=document.createElement('dialog');dialog.id='atlas-dialog';dialog.innerHTML='<button id="atlas-close">Close</button><h2>Saved discoveries</h2><p>Stored only in this browser. Clearing browser data removes these saves.</p><div id="atlas-favorites"></div>';document.body.append(dialog);count();document.querySelector('#atlas-save').onclick=()=>Atlas.save(document.title+' · '+(document.querySelector('input[type=search]')?.value||'current view'));document.querySelector('#atlas-share').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);message('Link copied. Favorites stay private to this browser.')}catch{message('Copy the link from your address bar.')}};function render(){document.querySelector('#atlas-favorites').innerHTML=get('atlas-favorites').filter(x=>safe(x.url)).map((x,i)=>`<p><a href="${esc(x.url)}">${esc(x.title)}</a> <button data-remove="${i}">Remove</button></p>`).join('')||'<p>No saves yet. Use Save view, or save an individual record.</p>'}document.querySelector('#atlas-saved').onclick=()=>{render();dialog.showModal()};document.querySelector('#atlas-close').onclick=()=>dialog.close();dialog.onclick=e=>{const b=e.target.closest('[data-remove]');if(b){const items=get('atlas-favorites').filter(x=>safe(x.url));items.splice(Number(b.dataset.remove),1);put('atlas-favorites',items);count();render()}};window.addEventListener('storage',count)});
})();
